import java.util.Arrays;

public class Solution {
    public static double secondSmallest(double[] arr) {
        if (arr.length < 2) {
            throw new IllegalArgumentException("Array must have at least two elements");
        }

        double smallest = Double.POSITIVE_INFINITY;
        double secondSmallest = Double.POSITIVE_INFINITY;

        for (double value : arr) {
            if (value < smallest) {
                secondSmallest = smallest;
                smallest = value;
            } else if (value > smallest && value < secondSmallest) {
                secondSmallest = value;
            }
        }

        if (secondSmallest == Double.POSITIVE_INFINITY) {
            throw new IllegalArgumentException("Array must have at least two distinct elements");
        }

        return secondSmallest;
    }

    public static void main(String[] args) {
        // Test case 1: Normal case with positive numbers
        double[] arr1 = {5.2, 3.1, 7.8, 3.1, 2.9, 4.5};
        System.out.println(secondSmallest(arr1));

        // Test case 2: Array with negative numbers
        double[] arr2 = {-5.0, -2.0, -8.0, -2.0, -1.0};
        System.out.println(secondSmallest(arr2));

        // Test case 3: Array with duplicates where smallest appears multiple times
        double[] arr3 = {1.0, 1.0, 2.0, 3.0, 4.0};
        System.out.println(secondSmallest(arr3));

        // Test case 4: Array with zero and negative values
        double[] arr4 = {0.0, -3.5, 2.1, -3.5, 0.0, 1.2};
        System.out.println(secondSmallest(arr4));

        // Test case 5: Array with very close floating point values
        double[] arr5 = {1.000001, 1.000000, 1.000002, 1.000000};
        System.out.println(secondSmallest(arr5));
    }
}
